def square_shape(g,pc):
    ys=[y for y,x in pc]; xs=[x for y,x in pc]
    h=max(ys)-min(ys)+1; w=max(xs)-min(xs)+1
    rect={(y,x) for y in range(min(ys),max(ys)+1) for x in range(min(xs),max(xs)+1)}
    return len(pc)==h*w and set(pc)==rect
