def comps_bg(g,bg,blocked=None):
    H,W=len(g),len(g[0]); seen=set(); res=[]
    for i in range(H):
        for j in range(W):
            if g[i][j]==bg and (i,j) not in (blocked or set()) and (i,j) not in seen:
                q=deque([(i,j)]); seen.add((i,j)); c=[(i,j)]
                while q:
                    y,x=q.popleft()
                    for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<H and 0<=nx<W and g[ny][nx]==bg and (ny,nx) not in seen:
                            seen.add((ny,nx)); q.append((ny,nx)); c.append((ny,nx))
                res.append(c)
    return res
