def enc_size(g,val):
    H,W=len(g),len(g[0]); res=[]
    for i in range(H):
        for j in range(W):
            if g[i][j]==val and all((i,y,x)==(i,j) or False for y,x in [(i-1,j),(i+1,j),(i,j-1),(i,j+1)]):
                pass
    seen=set()
    for i in range(H):
        for j in range(W):
            if g[i][j]==val and (i,j) not in seen:
                q=deque([(i,j)]); seen.add((i,j)); c=[(i,j)]
                while q:
                    y,x=q.popleft()
                    for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<H and 0<=nx<W and g[ny][nx]==val and (ny,nx) not in seen:
                            seen.add((ny,nx)); q.append((ny,nx)); c.append((ny,nx))
                tch=any(y==0 or y==H-1 or x==0 or x==W-1 for y,x in c)
                res.append((len(c),not tch))
    return res
