    if len(bs)>=2:
        p,q=bs[:2]
        my=(p[0]+q[0])//2; mx=(p[1]+q[1])//2
        w=[g[my+i][mx+j] for i in (-1,0,1) for j in (-1,0,1)]
        print('   center',(my,mx),'window',collections.Counter(w).most_common(3))
